INSERT INTO texts (id, type, filter_type, filter_content, text, title, default_order)
VALUES (
  1293,
  'ordinarium',
  'handle',
  'creed.apostles',
  '*Officiant and People together, all standing*' || char(10) || '' || char(10) || '    I believe in God, the Father almighty,' || char(10) || '        creator of heaven and earth.' || char(10) || '    I believe in Jesus Christ, his only Son, our Lord.' || char(10) || '        He was conceived by the Holy Spirit' || char(10) || '        and born of the Virgin Mary.' || char(10) || '        He suffered under Pontius Pilate,' || char(10) || '        was crucified, died, and was buried.' || char(10) || '        He descended to the dead.' || char(10) || '        On the third day he rose again.' || char(10) || '        He ascended into heaven,' || char(10) || '        and is seated at the right hand of the Father.' || char(10) || '        He will come again to judge the living and the dead.' || char(10) || '    I believe in the Holy Spirit,' || char(10) || '        the holy catholic Church,' || char(10) || '        the communion of saints,' || char(10) || '        the forgiveness of sins,' || char(10) || '        the resurrection of the body,' || char(10) || '        and the life everlasting. Amen.',
  'The Apostles’ Creed',
  NULL
);

INSERT INTO texts (id, type, filter_type, filter_content, text, title, default_order)
VALUES (
  1294,
  'ordinarium',
  'handle',
  'creed.athanasian',
  '    Whosoever will be saved, *' || char(10) || '        before all things it is necessary that he hold the Catholic Faith.' || char(10) || '    Which Faith except everyone do keep whole and undefiled, *' || char(10) || '        without doubt he shall perish everlastingly.' || char(10) || '    And the Catholic Faith is this: *' || char(10) || '        That we worship one God in Trinity, and Trinity in Unity,' || char(10) || '        Neither confounding the Persons, *' || char(10) || '        nor dividing the Substance.' || char(10) || '    For there is one Person of the Father, another of the Son, *' || char(10) || '        and another of the Holy Ghost.' || char(10) || '    But the Godhead of the Father, of the Son,' || char(10) || '        and of the Holy Ghost, is all one, *' || char(10) || '        the Glory equal, the Majesty co-eternal.' || char(10) || '    Such as the Father is, such is the Son, *' || char(10) || '        and such is the Holy Ghost.' || char(10) || '    The Father uncreate, the Son uncreate, *' || char(10) || '        and the Holy Ghost uncreate.' || char(10) || '    The Father incomprehensible, the Son incomprehensible, *' || char(10) || '        and the Holy Ghost incomprehensible.' || char(10) || '    The Father eternal, the Son eternal, *' || char(10) || '        and the Holy Ghost eternal.' || char(10) || '    And yet they are not three eternals, *' || char(10) || '        but one eternal.' || char(10) || '    As also there are not three incomprehensibles, nor three uncreated, *' || char(10) || '        but one uncreated, and one incomprehensible.' || char(10) || '    So likewise the Father is Almighty, the Son Almighty, *' || char(10) || '        and the Holy Ghost Almighty.' || char(10) || '    And yet they are not three Almighties, *' || char(10) || '        but one Almighty.' || char(10) || '    So the Father is God, the Son is God, *' || char(10) || '        and the Holy Ghost is God.' || char(10) || '    And yet they are not three Gods, *' || char(10) || '        but one God.' || char(10) || '    So likewise the Father is Lord, the Son Lord, *' || char(10) || '        and the Holy Ghost Lord.' || char(10) || '    And yet not three Lords, *' || char(10) || '        but one Lord.' || char(10) || '    For like as we are compelled by the Christian verity *' || char(10) || '        to acknowledge every Person by himself to be both God and Lord,' || char(10) || '    So are we forbidden by the Catholic Religion, *' || char(10) || '        to say, There be three Gods, or three Lords.' || char(10) || '    The Father is made of none, *' || char(10) || '        neither created, nor begotten.' || char(10) || '    The Son is of the Father alone, *' || char(10) || '        not made, nor created, but begotten.' || char(10) || '    The Holy Ghost is of the Father and of the Son, *' || char(10) || '        neither made, nor created, nor begotten, but proceeding.' || char(10) || '    So there is one Father, not three Fathers; one Son, not three Sons; *' || char(10) || '        one Holy Ghost, not three Holy Ghosts.' || char(10) || '    And in this Trinity none is afore, or after other; *' || char(10) || '        none is greater, or less than another;' || char(10) || '    But the whole three Persons are co-eternal together *' || char(10) || '        and co-equal.' || char(10) || '    So that in all things, as is aforesaid, *' || char(10) || '        the Unity in Trinity and the Trinity in Unity is to be worshipped.' || char(10) || '    He therefore that will be saved *' || char(10) || '        must thus think of the Trinity.' || char(10) || '' || char(10) || '    Furthermore, it is necessary to everlasting salvation *' || char(10) || '        that he also believe rightly the Incarnation of our Lord Jesus Christ.' || char(10) || '    For the right Faith is, that we believe and confess, *' || char(10) || '        that our Lord Jesus Christ, the Son of God, is God and Man;' || char(10) || '    God, of the Substance of the Father, begotten before the worlds; *' || char(10) || '        and Man, of the Substance of his Mother, born in the world;' || char(10) || '    Perfect God and perfect Man, *' || char(10) || '        of a reasonable soul and human flesh subsisting;' || char(10) || '    Equal to the Father, as touching his Godhead; *' || char(10) || '        and inferior to the Father, as touching his Manhood.' || char(10) || '    Who, although he be God and Man, *' || char(10) || '        yet he is not two, but one Christ;' || char(10) || '    One, not by conversion of the Godhead into flesh, *' || char(10) || '        but by taking of the Manhood into God;' || char(10) || '    One altogether; not by confusion of Substance, *' || char(10) || '        but by unity of Person.' || char(10) || '    For as the reasonable soul and flesh is one man, *' || char(10) || '        so God and Man is one Christ;' || char(10) || '    Who suffered for our salvation, *' || char(10) || '        descended into hell, rose again the third day from the dead.' || char(10) || '    He ascended into heaven, he sitteth on the right hand of the Father, God Almighty, *' || char(10) || '        from whence he shall come to judge the quick and the dead.' || char(10) || '    At whose coming all men shall rise again with their bodies *' || char(10) || '        and shall give account for their own works.' || char(10) || '    And they that have done good shall go into life everlasting; *' || char(10) || '        and they that have done evil into everlasting fire.' || char(10) || '    This is the Catholic Faith, *' || char(10) || '        which except a man believe faithfully, he cannot be saved.',
  'The Athanasian Creed',
  NULL
);

INSERT INTO texts (id, type, filter_type, filter_content, text, title, default_order)
VALUES (
  1295,
  'ordinarium',
  'handle',
  'confession.morning_prayer',
  '*The Officiant says to the People*' || char(10) || '' || char(10) || 'Dearly beloved, the Scriptures teach us to acknowledge our many sins and offenses, not concealing them from our heavenly Father, but confessing them with humble and obedient hearts that we may obtain forgiveness by his infinite goodness and mercy. We ought at all times humbly to acknowledge our sins before Almighty God, but especially when we come together in his presence to give thanks for the great benefits we have received at his hands, to declare his most worthy praise, to hear his holy Word, and to ask, for ourselves and on behalf of others, those things which are necessary for our life and our salvation. Therefore, draw near with me to the throne of heavenly grace.' || char(10) || '' || char(10) || '*or this*' || char(10) || '' || char(10) || 'Let us humbly confess our sins to Almighty God.' || char(10) || '' || char(10) || '*Silence is kept. All kneeling, the Officiant and People say*' || char(10) || '' || char(10) || '    Almighty and most merciful Father,' || char(10) || '        we have erred and strayed from your ways like lost sheep.' || char(10) || '    We have followed too much the devices and desires of our own hearts.' || char(10) || '    We have offended against your holy laws.' || char(10) || '    We have left undone those things which we ought to have done,' || char(10) || '        and we have done those things which we ought not to have done;' || char(10) || '        and apart from your grace, there is no health in us.' || char(10) || '    O Lord, have mercy upon us.' || char(10) || '        Spare all those who confess their faults.' || char(10) || '        Restore all those who are penitent, according to your promises declared to all people in Christ Jesus our Lord.' || char(10) || '    And grant, O most merciful Father, for his sake,' || char(10) || '        that we may now live a godly, righteous, and sober life,' || char(10) || '        to the glory of your holy Name. Amen.' || char(10) || '' || char(10) || '*The Priest alone stands and says*' || char(10) || '' || char(10) || 'Almighty God, the Father of our Lord Jesus Christ, desires not the death of sinners, but that they may turn from their wickedness and live. He has empowered and commanded his ministers to pronounce to his people, being penitent, the absolution and remission of their sins. He pardons and absolves all who truly repent and genuinely believe his holy Gospel. For this reason, we beseech him to grant us true repentance and his Holy Spirit, that our present deeds may please him, the rest of our lives may be pure and holy, and that at the last we may come to his eternal joy; through Jesus Christ our Lord. **Amen.**' || char(10) || '' || char(10) || '*or this*' || char(10) || '' || char(10) || 'The Almighty and merciful Lord grant you absolution and remission of all your sins, true repentance, amendment of life, and the grace and consolation of his Holy Spirit. **Amen.**' || char(10) || '' || char(10) || '*A Deacon or layperson remains kneeling and prays*' || char(10) || '' || char(10) || 'Grant to your faithful people, merciful Lord, pardon and peace; that we may be cleansed from all our sins, and serve you with a quiet mind; through Jesus Christ our Lord. **Amen.**',
  'The Confession and Absolution of Sin',
  NULL
);
